import json

from helpers import call, tools

import server

MEMORY_TOOLS = {"remember", "recall"}
ROBOTICS = "The robotics club meets Thursday at 7pm in Alden 109."
GROCERIES = "Buy oat milk and eggs on Saturday."
ESSAY = "The history essay is due Friday at noon."
CHESS = "The chess club meets Monday in Quigley Hall."


def test_the_server_offers_remember_and_recall() -> None:
    """Both memory tools are on offer."""
    assert MEMORY_TOOLS <= set(tools())


def test_the_server_offers_three_tools_of_its_own() -> None:
    """At least three tools besides remember and recall."""
    assert len(set(tools()) - MEMORY_TOOLS) >= 3


def test_one_tool_only_reads_and_one_changes_something() -> None:
    """Among your own tools, one is marked read-only and one is not."""
    marks = [
        tool.annotations
        for name, tool in tools().items()
        if name not in MEMORY_TOOLS
    ]
    assert any(mark and mark.read_only_hint is True for mark in marks)
    assert any(mark and mark.read_only_hint is False for mark in marks)


def test_remember_saves_the_note_to_the_memory_file() -> None:
    """A remembered note is in the file named by MEMORY afterwards."""
    result = call("remember", note=ROBOTICS)
    assert not result.startswith("error")
    assert "robotics club" in server.MEMORY.read_text()


def test_an_empty_note_is_an_error_result() -> None:
    """Nothing to remember is a mistake the model should hear about."""
    assert call("remember", note="   ").startswith("error")


def test_recall_finds_a_saved_note() -> None:
    """A note comes back for a query that shares its words."""
    call("remember", note=ROBOTICS)
    assert "Alden 109" in call("recall", query="robotics club")


def test_recall_puts_the_best_match_first() -> None:
    """The note that answers the query comes before a weaker match.

    The chess note shares one word with the query; the robotics note
    shares more. The chess note is saved first.
    """
    for note in (CHESS, GROCERIES, ROBOTICS, ESSAY):
        call("remember", note=note)
    result = call("recall", query="When does the robotics club meet?")
    first = result.find("robotics club")
    assert first != -1
    for other in ("chess club", "oat milk", "history essay"):
        assert other not in result or first < result.find(other)


def test_recall_returns_at_most_five_notes() -> None:
    """Eight matching notes are saved; at most five come back."""
    for number in range(8):
        call("remember", note=f"Club meeting number {number} is in Carnegie.")
    result = call("recall", query="club meeting")
    assert 1 <= result.count("Carnegie") <= 5


def test_recall_with_nothing_saved_still_answers() -> None:
    """An empty memory gives a result the model can read."""
    result = call("recall", query="robotics club")
    assert isinstance(result, str) and result.strip()


def test_memory_calls_are_logged() -> None:
    """Both memory tools go through run, so both are in the log."""
    call("remember", note=ROBOTICS)
    call("recall", query="robotics")
    logged = [
        json.loads(line)["tool"]
        for line in server.LOG.read_text().splitlines()
    ]
    assert logged[-2:] == ["remember", "recall"]
